<?php
use App\Models\ProductionCuringBatch;use App\Models\ProductionOrder;use App\Models\ProductionQualityInspection;use App\Models\ProductionQualityPlan;use App\Services\ProductionQualityService;use App\Support\CompanyFeatures;use function Livewire\Volt\{layout,mount,state};layout('layouts.app');
state(['context_type'=>'order','production_order_id'=>'','production_curing_batch_id'=>'','inspection_stage'=>'during_production','sample_quantity'=>'','inspected_quantity'=>'','passed_quantity'=>'','failed_quantity'=>'','corrective_action'=>'','retest_required'=>false,'notes'=>'','answers'=>[],'supersedes_inspection_id'=>null]);
mount(function(){abort_unless(CompanyFeatures::manufacturingEnabled()&&auth()->user()?->can('production.perform_quality_inspections'),403);if(request()->integer('retest')){$old=ProductionQualityInspection::query()->forCurrentCompany()->accessibleTo(auth()->user())->findOrFail(request()->integer('retest'));abort_unless(in_array($old->result,['failed','conditional'],true),422);$this->supersedes_inspection_id=$old->id;$this->context_type=$old->production_curing_batch_id?'batch':'order';$this->production_order_id=(string)$old->production_order_id;$this->production_curing_batch_id=(string)$old->production_curing_batch_id;$this->inspection_stage=$old->inspection_stage;}});
$updatedContextType=function(){$this->production_order_id='';$this->production_curing_batch_id='';$this->inspection_stage=$this->context_type==='batch'?'curing':'during_production';$this->answers=[];};
$currentPlan=function(){ $context=$this->context_type==='batch'?ProductionCuringBatch::query()->forCurrentCompany()->accessibleTo(auth()->user())->find($this->production_curing_batch_id):ProductionOrder::query()->forCurrentCompany()->find($this->production_order_id);if(!$context)return null;return ProductionQualityPlan::query()->where('product_id',$context->product_id)->where('inspection_stage',$this->inspection_stage)->where('status','active')->with(['checks.unit','product'])->first();};
$save=function(){ $inspection=app(ProductionQualityService::class)->createInspection(['production_order_id'=>$this->context_type==='order'?$this->production_order_id:null,'production_curing_batch_id'=>$this->context_type==='batch'?$this->production_curing_batch_id:null,'inspection_stage'=>$this->inspection_stage,'sample_quantity'=>$this->sample_quantity,'inspected_quantity'=>$this->inspected_quantity,'passed_quantity'=>$this->passed_quantity,'failed_quantity'=>$this->failed_quantity,'corrective_action'=>$this->corrective_action,'retest_required'=>$this->retest_required,'notes'=>$this->notes,'supersedes_inspection_id'=>$this->supersedes_inspection_id],$this->answers,auth()->user());session()->flash('success',__('application.quality_inspection_recorded_a5dd1bed'));$this->redirectRoute('production.quality.inspections.show',$inspection,navigate:true);};
?>
<div><x-page-header :title="$supersedes_inspection_id?__('terminology.create_retest_afa0f2aa'):__('terminology.create_inspection_6091a14d')" description="{{ __('application.objective_checks_are_evaluated_on_the_server_against_the_active_plan_snapsh_6fae394d') }}" :breadcrumbs="[__('production.quality.inspections')=>route('production.quality.inspections.index'),'Create'=>null]"/><form wire:submit="save" class="space-y-5"><x-card><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><label class="text-sm font-bold">{{ __('application.context_cc11b3a2') }}<select wire:model.live="context_type" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="order">{{ __('application.production_order_4774754a') }}</option><option value="batch">{{ __('application.curing_batch_ea4cae93') }}</option></select></label>@if($context_type==='order')<label class="text-sm font-bold">{{ __('application.order_1d75774c') }}<select wire:model.live="production_order_id" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="">{{ __('application.select_order_9727bea9') }}</option>@foreach(ProductionOrder::query()->forCurrentCompany()->with('product')->latest('production_date')->limit(200)->get() as $o)<option value="{{$o->id}}">{{$o->order_number}} · {{$o->product?->name}}</option>@endforeach</select></label><label class="text-sm font-bold">{{ __('application.stage_ca6d0e3a') }}<select wire:model.live="inspection_stage" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950">@foreach(['raw_material','during_production','production_completion'] as $v)<option value="{{$v}}">{{\App\Support\UiText::label($v)}}</option>@endforeach</select></label>@else<label class="text-sm font-bold">{{ __('application.curing_batch_ea4cae93') }}<select wire:model.live="production_curing_batch_id" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="">{{ __('application.select_batch_1e0c94a5') }}</option>@foreach(ProductionCuringBatch::query()->forCurrentCompany()->accessibleTo(auth()->user())->with('product')->latest('production_date')->limit(200)->get() as $b)<option value="{{$b->id}}">{{$b->batch_number}} · {{$b->product?->name}}</option>@endforeach</select></label><label class="text-sm font-bold">{{ __('application.stage_ca6d0e3a') }}<select wire:model.live="inspection_stage" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="curing">{{ __('application.curing_13ba4ca8') }}</option><option value="pre_release">{{ __('application.pre_release_160cc0b8') }}</option></select></label>@endif</div></x-card>
@php($activePlan=$this->currentPlan()) @if($activePlan)<x-card><h2 class="mb-1 text-lg font-black">{{$activePlan->name}} <span class="text-sm text-slate-500">v{{$activePlan->version}}</span></h2><p class="mb-4 text-sm text-slate-500">{{$activePlan->product?->name}} · {{\App\Support\UiText::label($activePlan->inspection_stage)}}</p><div class="space-y-4">@foreach($activePlan->checks as $check)<div wire:key="inspection-check-{{$check->id}}" class="grid gap-3 rounded-xl border border-slate-200 p-4 md:grid-cols-4 dark:border-slate-700"><div><p class="font-black">{{$check->name}}</p><p class="text-xs text-slate-500">{{\App\Support\UiText::label($check->acceptance_rule)}}@if($check->critical) {{ __('application.critical_0f26eb1d') }} @endif</p></div><div>@if($check->check_type==='numeric')<x-form-input label="{{ __('application.actual_7bb2ee60') }}" name="answers.{{$check->id}}.numeric_value" wire:model="answers.{{$check->id}}.numeric_value"/>@elseif($check->check_type==='yes_no')<label class="text-sm font-bold">{{ __('application.actual_7bb2ee60') }}<select wire:model="answers.{{$check->id}}.boolean_value" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="">{{ __('application.select_85982229') }}</option><option value="1">{{ __('application.yes_5397e058') }}</option><option value="0">{{ __('application.no_816c52fd') }}</option></select></label>@elseif($check->check_type==='selection')<label class="text-sm font-bold">{{ __('application.actual_7bb2ee60') }}<select wire:model="answers.{{$check->id}}.selected_value" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="">{{ __('application.select_85982229') }}</option>@foreach($check->allowed_options??[] as $v)<option value="{{$v}}">{{$v}}</option>@endforeach</select></label>@else<label class="text-sm font-bold">{{ __('application.actual_7bb2ee60') }}<textarea wire:model="answers.{{$check->id}}.text_value" class="mt-1 block w-full rounded-lg border-slate-200